import time
import logging
from taf.ul.mobile.ui.android.mobiles.huawei.emui_10_1_0_huawei_lio_an00 import EMUI1010HuaWeiLioAn00
from taf.ul.mobile.ui.android.exceptions import SelectFailure


class EMUI1010HuaweiEvrAn900(EMUI1010HuaWeiLioAn00):

    def switch_network_mode(self, mode_name, restart_time):
        if self._get_configured_network_mode_name() == mode_name:
            logging.info("has selected specified mode, no action")
            self._close_setting()
            return

        self._select_5g_network_mode(mode_name)
        time.sleep(restart_time)

        if self._get_configured_network_mode_name() != mode_name:
            raise SelectFailure(mode_name)

        self._close_setting()

    def get_network_mode(self):
        network_mode = self._get_configured_network_mode_name()
        self._close_setting()
        return network_mode

    def _select_5g_network_mode(self, mode_name):
        self._open_menu_by_searching_in_settings("5G network mode")
        self._tap_5g_network_mode()
        self._click_menu(mode_name)

    def _get_configured_network_mode_name(self):
        self._open_menu_by_searching_in_settings("5G network mode")
        self._tap_5g_network_mode()
        return self._get_selected_node_title_in_dialog()

    def get_access_point_name(self):
        self._open_menu_by_searching_in_settings("Access Point Names (APNs)")
        self._tap_access_point_names()
        apn = self._get_selected_node_title()
        self._close_setting()
        return apn
